contract InvMutTest {
  C c;
  constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
  function test(address to, uint256 amount) public {
    require(to != address(0));
    require(c.balanceOf(address(this)) >= amount);
    require(!c.frozenAccount(address(this)) && !c.frozenAccount(to));
    bool r = c.transfer(to, amount); if (__ESBMC_reverted()) return;
    assert(r == true);
  }
  receive() external payable {}
  fallback() external payable {}
}

